{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "The closest structural analogue, [18F]SP203, shares the 3-fluoro-5-ethynylbenzonitrile core with the query and showed high BBB permeability in human PET studies (%SUV ~580), directly supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The closely related mGluR5 ligand [11C]MPEPy, which contains the same 2-pyridylethynyl motif, easily crosses the BBB despite being a P-gp substrate, indicating that efflux does not preclude meaningful brain entry for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A biodistribution study in mice showed that [11C]remodelin, a small-molecule radiotracer with moderate lipophilicity, reached 4.43% ID/g in brain at 1 minute, demonstrating rapid brain penetration consistent with the query's properties.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "PET examination of [18F]FPTQ showed rapid influx into mouse cerebellum reaching 2.5% ID/g within minutes, supporting that this class of heteroaryl-alkynyl radiotracers readily crosses the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a known mGluR5-oriented 3-fluoro-5-(pyridinylethynyl)benzonitrile scaffold. The closest analogue, [18F]SP203, demonstrates high BBB permeability in humans, and multiple related radiotracers show rapid brain uptake in preclinical models. Even where P-gp efflux is present, brain entry remains meaningful. Therefore the query is predicted to have adequate CNS access.",
  "evidence_gaps": [
    "No direct quantitative brain-to-plasma or unbound brain concentration measurement is available for the exact query molecule.",
    "The query's specific P-gp or other efflux-transporter liability is not directly measured, though related analogues show that efflux does not prevent meaningful CNS exposure.",
    "Human data are available only for the close analogue [18F]SP203, not for the exact query structure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

